model_safe_stan:
// ForestDB translation: Pragmatics with Semantic Free Variables
data {
  int<lower=1> N;
  array[N] int<lower=0, upper=1> y;
}
parameters {
  real<lower=0, upper=1> theta;
}
model {
  theta ~ beta(1, 1);
  y ~ bernoulli(theta);
}
generated quantities {
  real expected_successes = N * theta;
}
